@layer components {
  .article-preview {
    color: var(--shelf-article-preview-fgColor-default);
    background-color: var(--shelf-article-preview-bgColor-default);
  }

  .article-preview-title {
    color: var(--shelf-article-preview-fgColor-title);
    font-size: var(--shelf-article-preview-fontSize-title);
    font-weight: var(--shelf-article-preview-fontWeight-title);
    line-height: var(--shelf-article-preview-lineHeight-tight);
  }

  .article-preview-excerpt {
    color: var(--shelf-article-preview-fgColor-excerpt);
    font-size: var(--shelf-article-preview-fontSize-excerpt);
    line-height: var(--shelf-article-preview-lineHeight-normal);
  }
}
